begin;
grant workspace_admin_owner,workspace_context_owner to current_user;
insert into public.election(id,year,round) values('54000000-0000-0000-0000-000000000001',2099,'generales');
insert into public.category(id,name) values('54000000-0000-0000-0000-000000000002','PRESIDENTE'),('54000000-0000-0000-0000-000000000007','REFERENCE OVERFLOW');
insert into public.jurisdiction(id,distrito_code,seccion_code,seccion_name,distrito_name,circuito_code,establecimiento_code,establecimiento_name,mesa_code) values('54000000-0000-0000-0000-000000000003','99','999','Exact','Buenos Aires','00001','E1','School one',7);
insert into public.party_canonical(id,display_name) values('projection-party','Projection Party');
insert into public.party_mapping(year,jurisdiction,category,list_id,canonical_party_id) values(2099,'national','PRESIDENTE','A','projection-party');
insert into public.jurisdiction(id,distrito_code,seccion_code,seccion_name,distrito_name,circuito_code,establecimiento_code,establecimiento_name,mesa_code) select ('54000000-0000-0000-0001-'||lpad(g::text,12,'0'))::uuid,'99','999','Exact','Buenos Aires','00001','E1','School one',g+7 from generate_series(1,200) g;
insert into public.result_row(election_id,jurisdiction_id,category_id,granularity,list_id,votes,source_kind,archive_entry_id,source_row_index) values('54000000-0000-0000-0000-000000000001','54000000-0000-0000-0000-000000000003','54000000-0000-0000-0000-000000000002','mesa','A',10,'official','national/2099-generales',1),('54000000-0000-0000-0000-000000000001','54000000-0000-0000-0000-000000000003','54000000-0000-0000-0000-000000000007','mesa','A',10,'official','national/2099-overflow',1);
insert into public.result_row(election_id,jurisdiction_id,category_id,granularity,list_id,votes,source_kind,archive_entry_id,source_row_index) select '54000000-0000-0000-0000-000000000001',('54000000-0000-0000-0001-'||lpad(g::text,12,'0'))::uuid,'54000000-0000-0000-0000-000000000002','mesa','A',10,'official','national/2099-generales',g+1 from generate_series(1,152) g;
insert into public.result_row(election_id,jurisdiction_id,category_id,granularity,list_id,votes,source_kind,archive_entry_id,source_row_index) select '54000000-0000-0000-0000-000000000001',('54000000-0000-0000-0001-'||lpad(g::text,12,'0'))::uuid,'54000000-0000-0000-0000-000000000007','mesa','A',10,'official','national/2099-overflow',g+1 from generate_series(1,200) g;
set local role workspace_admin_owner;
insert into workspace_private.organization(id,slug,display_name,entitlement_revision) values('54000000-0000-0000-0000-000000000004','projection-one','Projection One',1);
insert into workspace_private.organization_membership(organization_id,user_id,membership_revision) values('54000000-0000-0000-0000-000000000004','54000000-0000-0000-0000-000000000005',1);
insert into workspace_private.section_scope values('99','999');
insert into workspace_private.organization_section_entitlement(organization_id,distrito_code,seccion_code) values('54000000-0000-0000-0000-000000000004','99','999');
reset role; set local role workspace_context_owner;
insert into workspace_private.workspace_context(session_id,user_id,organization_id,membership_revision,entitlement_revision,context_revision,fixed_expires_at) values('54000000-0000-0000-0000-000000000006','54000000-0000-0000-0000-000000000005','54000000-0000-0000-0000-000000000004',1,1,1,statement_timestamp()+interval '1 hour');
reset role;
select plan(15);
select ok(to_regprocedure('workspace_api.official_schools(uuid,uuid,text,text)') is not null and to_regprocedure('workspace_api.official_reference(uuid,uuid,text,text)') is not null and to_regprocedure('workspace_api.official_provenance(uuid,uuid,text,text)') is not null,'authorized projection functions exist');
select ok((select bool_and(r.rolname='workspace_query_owner') from pg_proc p join pg_roles r on r.oid=p.proowner where p.oid in ('workspace_api.official_schools(uuid,uuid,text,text)'::regprocedure,'workspace_api.official_reference(uuid,uuid,text,text)'::regprocedure,'workspace_api.official_provenance(uuid,uuid,text,text)'::regprocedure)),'projection functions retain the query owner');
select ok((select bool_and(p.prosecdef) and bool_and(regexp_replace(array_to_string(p.proconfig,','),'\s+','','g') in ('search_path=pg_catalog,workspace_private,public,pg_temp','search_path=pg_catalog,workspace_api,public,pg_temp')) from pg_proc p where p.oid in ('workspace_api.official_schools(uuid,uuid,text,text)'::regprocedure,'workspace_api.official_reference(uuid,uuid,text,text)'::regprocedure,'workspace_api.official_provenance(uuid,uuid,text,text)'::regprocedure)),'projection functions pin their search paths');
select ok(has_function_privilege('authenticated','workspace_api.official_schools(uuid,uuid,text,text)','EXECUTE') and has_function_privilege('authenticated','workspace_api.official_reference(uuid,uuid,text,text)','EXECUTE') and has_function_privilege('authenticated','workspace_api.official_provenance(uuid,uuid,text,text)','EXECUTE') and not has_function_privilege('anon','workspace_api.official_schools(uuid,uuid,text,text)','EXECUTE') and not has_function_privilege('anon','workspace_api.official_reference(uuid,uuid,text,text)','EXECUTE') and not has_function_privilege('anon','workspace_api.official_provenance(uuid,uuid,text,text)','EXECUTE') and (to_regrole('service_role') is null or (not has_function_privilege('service_role','workspace_api.official_schools(uuid,uuid,text,text)','EXECUTE') and not has_function_privilege('service_role','workspace_api.official_reference(uuid,uuid,text,text)','EXECUTE') and not has_function_privilege('service_role','workspace_api.official_provenance(uuid,uuid,text,text)','EXECUTE'))),'only authenticated receives projection execute');
select ok(not exists(select from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a where p.oid in ('workspace_api.official_schools(uuid,uuid,text,text)'::regprocedure,'workspace_api.official_reference(uuid,uuid,text,text)'::regprocedure,'workspace_api.official_provenance(uuid,uuid,text,text)'::regprocedure) and a.grantee=0 and a.privilege_type='EXECUTE'),'PUBLIC retains no execute path');
select ok((select strpos(d,'authorized_section_scopes()')<strpos(d,'results_exploration_schools(') and d like '%octet_length(payload::text)>120000%' from (select regexp_replace(lower(pg_get_functiondef('workspace_api.official_schools(uuid,uuid,text,text)'::regprocedure)),'\s+','','g') d) f),'schools authorize before the bounded public projection');
select ok((select strpos(d,'authorized_section_scopes()')<strpos(d,'public.result_row') and d like '%rr.source_kind=''official''%' and d like '%j.seccion_code=p_seccion_code%' and d like '%source_exclusions%' and d like '%rr.source_kindisdistinctfrom''official''%' and d like '%coalesce(rr.source_kind,''unknown'')%' and d like '%non_official_source%' and d like '%''rows''%' and d not like '%''votes''%' and d like '%limit200%' from (select regexp_replace(lower(pg_get_functiondef('workspace_api.official_reference(uuid,uuid,text,text)'::regprocedure)),'\s+','','g') d) f),'reference IDs are exact-section authorized, official-only, and bounded at 200');
select ok((select strpos(d,'official_result(')<strpos(d,'public.archive_entry') and d like '%source_kind=''official''%' and d like '%source_exclusions%' and d not like '%source_url%' and d not like '%archived_path%' and d not like '%notes%' from (select regexp_replace(lower(pg_get_functiondef('workspace_api.official_provenance(uuid,uuid,text,text)'::regprocedure)),'\s+','','g') d) f),'provenance authorizes through official result before safe archive metadata');
select ok((select indisvalid and indisready from pg_index where indexrelid='public.result_row_authorized_official_facets_idx'::regclass) and (select indisvalid and indisready from pg_index where indexrelid='public.result_row_official_district_scope_idx'::regclass) and (select indisvalid and indisready from pg_index where indexrelid='public.archive_entry_pkey'::regclass),'projection access paths retain valid production indexes');
select ok(has_table_privilege('workspace_query_owner','public.party_mapping','SELECT') and has_table_privilege('workspace_query_owner','public.party_canonical','SELECT') and not has_table_privilege('authenticated','public.party_mapping','SELECT') and not has_table_privilege('authenticated','public.party_canonical','SELECT') and not exists(select from unnest(array['anon','service_role']) r,unnest(array['party_mapping','party_canonical']) t where to_regrole(r) is not null and has_table_privilege(r,'public.'||t,'SELECT')),'query-owner lookup access remains while direct client reads stay denied');
select is((select array_agg(tablename||':'||policyname order by tablename) from pg_policies where schemaname='public' and tablename=any(array['party_mapping','party_canonical']) and cmd='SELECT' and roles=array['workspace_query_owner']::name[] and qual='true' and with_check is null),array['party_canonical:workspace_query_owner_party_canonical_select','party_mapping:workspace_query_owner_party_mapping_select']::text[],'party lookups have exact query-owner SELECT policies');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub','54000000-0000-0000-0000-000000000005','session_id','54000000-0000-0000-0000-000000000006','exp',floor(extract(epoch from statement_timestamp()+interval '10 minutes')))::text,true);
select is(workspace_api.official_schools('54000000-0000-0000-0000-000000000001','54000000-0000-0000-0000-000000000002','99','999')->>'status','ok','authorized official schools succeeds through the query owner');
select is(workspace_api.official_schools('54000000-0000-0000-0000-000000000001','54000000-0000-0000-0000-000000000002','99','999')->'schools'->0->'parties'->0->>'canonical_party_id','projection-party','authorized schools resolves the canonical party without direct client access');
select ok((select p->>'status'='ok' and p->>'total'='153' and jsonb_array_length(p->'items')=153 and p->>'truncated'='false' from (select workspace_api.official_reference('54000000-0000-0000-0000-000000000001','54000000-0000-0000-0000-000000000002','99','999') p) x),'the complete known 153-mesa reference fits the documented bound');
select ok((select p->>'status'='ok' and p->>'total'='201' and jsonb_array_length(p->'items')=200 and p->>'truncated'='true' from (select workspace_api.official_reference('54000000-0000-0000-0000-000000000001','54000000-0000-0000-0000-000000000007','99','999') p) x),'the 201st reference is explicitly truncated rather than silently malformed');
select * from finish();
rollback;
